changes.old:
/* Keep Resize field names and guidance readable in the light theme. */
html:not([data-portal-theme="dark"]) .portal-page.portal-image-resize .portal-field > label {
  color: var(--portal-text);
}
html:not([data-portal-theme="dark"]) .portal-page.portal-image-resize .portal-field-help {
  color: var(--portal-muted);
}

changes.new:
/* Keep Resize field names and guidance readable in the light theme. */
html:not([data-portal-theme="dark"]) .portal-page.portal-image-resize .portal-field > label {
  color: var(--portal-text);
}
html:not([data-portal-theme="dark"]) .portal-page.portal-image-resize .portal-field-help {
  color: var(--portal-muted);
}

/* Keep Resize controls at their natural height beside the source picker. */
.portal-page.portal-image-resize form[data-portal-action="image-operation-resize"] > .portal-fields > .portal-field {
  align-content: start;
}
